"""lctx.py <hexaddr> [before] [after]: lines of the whole-image listing (regenerated by tools/disassemble.py) around an address."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fcommon import listing
lst = listing()
a = int(sys.argv[1], 16); b = int(sys.argv[2]) if len(sys.argv) > 2 else 14; f = int(sys.argv[3]) if len(sys.argv) > 3 else 4
for i, l in enumerate(lst):
    if l.strip().startswith(f"${a:06x}:"):
        print("\n".join(lst[max(0, i - b): i + f + 1])); break
